731	// ── New session wizard ────────────────────────────────────────────────────────
732	
733	/// A 4-step panel drawn over the bottom of the screen. Each completed step
734	/// stays visible with its confirmed value while the user fills the next one.
735	fn new_session_wizard(stdout: &mut impl Write, repo_dir: &str, w: usize, h: usize) -> Option<NewSessionConfig> {
736	    const LABEL_W: usize = 24;
737	    // Panel rows: title, blank, agent, branch, name, prompt, blank  (7 rows + 1 status bar)
738	    const PANEL_H: usize = 7;
739	
740	    let panel_top = h.saturating_sub(PANEL_H + 1);
741	
742	    let mut step = 0usize;           // 0=agent 1=branch 2=name 3=prompt
743	    let mut agent_sel = 0usize;
744	    let mut confirmed_agent = 0usize;
745	    let mut inputs = [String::new(), String::new(), String::new()]; // branch, name, prompt
746	
747	    execute!(stdout, cursor::Show).ok();
748	
749	    loop {
750	        // ── Draw panel ────────────────────────────────────────────────────────
751	        // Title row
752	        execute!(stdout, cursor::MoveTo(0, panel_top as u16)).ok();
753	        write!(stdout, "\x1b[1;38;5;229m  New Session\x1b[0m").ok();
754	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
755	
756	        // Blank separator
757	        execute!(stdout, cursor::MoveTo(0, (panel_top + 1) as u16)).ok();
758	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
759	
760	        let step_rows  = [panel_top + 2, panel_top + 3, panel_top + 4, panel_top + 5];
761	        let step_labels = ["  Agent", "  Worktree branch", "  Session name", "  Prompt"];
762	
763	        for (i, (&row, &label)) in step_rows.iter().zip(step_labels.iter()).enumerate() {
764	            execute!(stdout, cursor::MoveTo(0, row as u16)).ok();
765	            let lpart = format!("{label:<LABEL_W$}");
766	
767	            if i < step {
768	                // Completed — dim label, value in colour
769	                let val = if i == 0 {
770	                    let (name, _, col) = AGENTS[confirmed_agent];
771	                    format!("\x1b[38;5;{col}m{name}\x1b[0m")
772	                } else {
773	                    let v = inputs[i - 1].trim();
774	                    if v.is_empty() { "\x1b[38;5;238m(skip)\x1b[0m".to_string() }
775	                    else            { format!("\x1b[38;5;255m{v}\x1b[0m") }
776	                };
777	                write!(stdout, "\x1b[38;5;240m{lpart}\x1b[0m{val}").ok();
778	            } else if i == step {
779	                // Active step
780	                write!(stdout, "\x1b[38;5;255m{lpart}\x1b[0m").ok();
781	                if i == 0 {
782	                    // Inline agent picker
783	                    for (ai, (name, _, col)) in AGENTS.iter().enumerate() {
784	                        if ai > 0 { write!(stdout, "\x1b[38;5;238m │ \x1b[0m").ok(); }
785	                        if ai == agent_sel {
786	                            write!(stdout, "\x1b[48;5;236;38;5;{col}m {name} \x1b[0m").ok();
787	                        } else {
788	                            write!(stdout, "\x1b[38;5;240m {name}\x1b[0m").ok();
789	                        }
790	                    }
791	                } else {
792	                    // Text input — print typed chars, terminal cursor sits here
793	                    write!(stdout, "\x1b[38;5;255m{}\x1b[0m", inputs[i - 1]).ok();
794	                }
795	            } else {
796	                // Future step — very dim label only
797	                write!(stdout, "\x1b[38;5;238m{lpart}\x1b[0m").ok();
798	            }
799	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
800	        }
801	
802	        // Trailing blank row
803	        let blank2 = panel_top + 6;
804	        if blank2 < h.saturating_sub(1) {
805	            execute!(stdout, cursor::MoveTo(0, blank2 as u16)).ok();
806	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
807	        }
808	
809	        // Status bar hint
810	        let bar = if step == 0 {
811	            "  ↑↓/jk: select agent   enter: confirm   esc: cancel  "
812	        } else {
813	            "  type to enter   enter: next   esc: cancel  "
814	        };
815	        draw_status(stdout, bar, w, h).ok();
816	
817	        // Position terminal cursor for text input steps
818	        if step > 0 {
819	            let row = step_rows[step];
820	            let col = (LABEL_W + inputs[step - 1].len()).min(w.saturating_sub(1));
821	            execute!(stdout, cursor::MoveTo(col as u16, row as u16)).ok();
822	        }
823	        stdout.flush().ok();
824	
825	        // ── Handle input ──────────────────────────────────────────────────────
826	        match event::read().ok()? {
827	            Event::Key(k) => match k.code {
828	                KeyCode::Esc => {
829	                    execute!(stdout, cursor::Hide).ok();
830	                    return None;
831	                }
832	                KeyCode::Up   | KeyCode::Char('k') if step == 0 => {
833	                    if agent_sel > 0 { agent_sel -= 1; }
834	                }
835	                KeyCode::Down | KeyCode::Char('j') if step == 0 => {
836	                    if agent_sel + 1 < AGENTS.len() { agent_sel += 1; }
837	                }
838	                KeyCode::Backspace if step > 0 => {
839	                    inputs[step - 1].pop();
840	                }
841	                KeyCode::Char(c) if step > 0 && !k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
842	                    inputs[step - 1].push(c);
843	                }
844	                KeyCode::Enter => match step {
845	                    0 => { confirmed_agent = agent_sel; step = 1; }
846	                    1 | 2 => { step += 1; }
847	                    _ => {
848	                        execute!(stdout, cursor::Hide).ok();
849	                        let (agent_name, agent_cli, _) = AGENTS[confirmed_agent];
850	                        let branch_raw = inputs[0].trim().to_string();
851	                        return Some(NewSessionConfig {
852	                            agent_name: agent_name.to_string(),
853	                            agent_cli: agent_cli.to_string(),
854	                            branch: if branch_raw.is_empty() { None } else { Some(branch_raw) },
855	                            session_name: inputs[1].trim().to_string(),
856	                            prompt: inputs[2].trim().to_string(),
857	                            repo_dir: repo_dir.to_string(),
858	                        });
859	                    }
860	                },
861	                _ => {}
862	            },
863	            _ => {}
864	        }
865	    }
866	}
